exports.init = (params, rng) => {
  const W = 80;
  const Hgrid = 30;
  const initH = params.initialHeight ?? 10;
  const Lstoss0 = initH * 2;
  const crest0 = Math.min(W - initH - 5, Lstoss0 + 5);
  return {
    W: W,
    Hgrid: Hgrid,
    crestPos: crest0,
    initialCrest: crest0,
    initialHeight: initH,
    steps: 0,
    lastQ: 0,
    lastC: 0,
    lastStossRate: 0
  };
};
exports.step = (state, params, rng) => {
  const W = state.W;
  const Hgrid = state.Hgrid;
  const initH = params.initialHeight ?? state.initialHeight;
  const wind = params.windSpeed ?? 5;
  const threshold = 3.5;
  const k = 0.005;
  const rho = 1;
  const diff = Math.max(0, wind - threshold);
  const Q = k * Math.pow(diff, 1.5);
  const H = Math.max(1, initH);
  const c = Q / (rho * H);
  const newCrest = state.crestPos + c;
  const Lstoss = H * 2;
  const slope = H / Lstoss;
  const stossRate = -c * slope * 10;
  return {
    W: W,
    Hgrid: Hgrid,
    crestPos: newCrest,
    initialCrest: state.initialCrest,
    initialHeight: initH,
    steps: state.steps + 1,
    lastQ: Q,
    lastC: c,
    lastStossRate: stossRate
  };
};
exports.observe = (state, params) => {
  const W = state.W;
  const moved = state.crestPos - state.initialCrest;
  // Measured from the state: how far the crest walked per step, in dune widths per 10,000 steps.
  const pace = state.steps > 0 ? (moved / state.steps) * 10000 / W : 0;
  return {
    crestDisplacement: moved / W,
    migrationSpeed: pace,
    stossErosionRate: state.lastStossRate
  };
};
exports.view = (state, params) => {
  const H = Math.max(1, params.initialHeight ?? state.initialHeight);
  const Lstoss = H * 2;
  const Llee = H * 1;
  const left = state.initialCrest - Lstoss - 6;
  const cols = Math.ceil(Lstoss + Llee + 36);
  const rows = state.Hgrid;
  const grid = [];
  for (let y = 0; y < rows; y++) {
    const row = [];
    for (let col = 0; col < cols; col++) {
      const x = left + col;
      const dx = x - state.crestPos;
      let h = 0;
      if (dx >= -Lstoss && dx <= 0) h = H * (1 + dx / Lstoss);
      else if (dx > 0 && dx <= Llee) h = H * (1 - dx / Llee);
      const thresholdY = rows - h;
      row.push(y >= thresholdY ? 1 : 0);
    }
    grid.push(row);
  }
  return { kind: 'field', grid: grid, w: cols, h: rows };
};
